  document.querySelectorAll("[data-frame-material]").forEach(el=>el.addEventListener("change",()=>{const [si,ri,ruleId]=el.dataset.frameMaterial.split(":"),row=state.doc.takeoff_sections[Number(si)].lines[Number(ri)],all=(state.config?.material_rules||[]).map(x=>x.id),prior=[...(row.installation_material_ids??all)],next=new Set(prior);el.checked?next.add(ruleId):next.delete(ruleId);row.installation_material_ids=all.filter(id=>next.has(id));markDirty({path:`takeoff_sections.${si}.lines.${ri}.installation_material_ids`,prior,new:row.installation_material_ids,reason:"Frame-line installation material applicability changed"})}));
